package vn.svframe.svframelib.api.crafting.outputs; import vn.svframe.svframelib.api.crafting.ingredients.*; import vn.svframe.svframelib.api.crafting.recipes.*; import vn.svframe.svframelib.api.crafting.recipes.vmp.VanillaInventoryMapping; import net.minecraft.item.ItemStack; import net.minecraft.server.network.ServerPlayerEntity; import java.util.*; public class MRORecipe extends SVFrameRecipeOutput implements VanillaBookableOutput { private final ShapedRecipe output; private SVFrameRecipe mainConsumption; private final Map<String,SVFrameRecipe> side=new LinkedHashMap<>(); public MRORecipe(ShapedRecipe output){this.output=output;} public MRORecipe(ShapedRecipe output,ShapedRecipe consumption){this.output=output;this.mainConsumption=consumption;} public ShapedRecipe getOutput(){return output;} public SVFrameRecipe getMainInputConsumption(){return mainConsumption;} public void setMainInputConsumption(SVFrameRecipe r){mainConsumption=r;} public boolean hasInputConsumption(){return mainConsumption!=null;} public ArrayList<String> getSideConsumptionNames(){return new ArrayList<>(side.keySet());} public SVFrameRecipe getSideConsumption(String n){return side.get(n);} public boolean hasSideConsumption(String n){return side.containsKey(n);} public void setSideConsumption(String n,SVFrameRecipe r){if(r==null)side.remove(n);else side.put(n,r);} public SVFrameRecipe ifEmptyNull(SVFrameRecipe r){return r!=null&&r.getIngredients().isEmpty()?null:r;} public boolean isRandom(){return false;} public void analyzeDetermination(){} public SVFrameRecipeInventory applyDisplay(SVFrameBlueprintInventory input,ServerPlayerEntity player,VanillaInventoryMapping mapping){SVFrameRecipeInventory result=new SVFrameRecipeInventory();for(SVFrameRecipeIngredient raw:output.getIngredients()){ShapedIngredient i=(ShapedIngredient)raw;ItemStack s=i.getIngredient().getRandomDisplayItem(null);result.setItemAt(i.getHorizontalOffset(),i.getVerticalOffset(),s);}return result;} public void applyResult(SVFrameRecipeInventory result,SVFrameBlueprintInventory input,SVFrameCachedResult cache,ServerPlayerEntity player,VanillaInventoryMapping mapping,int amount){processInventory(result,applyDisplay(input,player,mapping),amount);} public static ArrayList<ItemStack> toItemsList(SVFrameRecipeInventory inv){ArrayList<ItemStack> out=new ArrayList<>();for(int y=0;y<inv.getHeight();y++)for(int x=0;x<inv.getWidth();x++){ItemStack s=inv.getItemAt(x,y);if(!s.isEmpty())out.add(s.copy());}return out;} }
